generic_start:
G90 ;absolute coordinates
M83 ;relative extrusion
M140 S{bed}
M190 S{bed}
M104 S{noz}
M109 S{noz}
G28 ;home
G92 E0
G1 Z0.3 F600
G1 X{px0} Y2 F3000
G1 X{px1} Y2 E18 F900 ;prime line
G92 E0
G1 E-0.4 F1800

printers.end:
{if max_layer_z < max_print_height}G1 Z{z_offset+min(max_layer_z+2, max_print_height)} F600 ; Move print head up{endif}
G1 X5 Y{print_bed_max[1]*0.85} F{travel_speed*60} ; present print
{if max_layer_z < max_print_height-10}G1 Z{z_offset+min(max_layer_z+70, max_print_height-10)} F600 ; Move print head further up{endif}
{if max_layer_z < max_print_height*0.6}G1 Z{max_print_height*0.6} F600 ; Move print head further up{endif}
M140 S0 ; turn off heatbed
M104 S0 ; turn off temperature
M107 ; turn off fan
M84; disable motors                    ; disable stepper motors

